// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addToBagWithQuantity } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // Sunglasses (OLJCESPC7Z) unit price and the quantity this test selects.
    // Quantity 7 is only selectable because this PR added options 6-9 to the Qty select.
    const unitPrice = 19.99;
    const quantity = 7;
    const shipping = 8.99;

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.waitForLoadState('networkidle');

    await addToBagWithQuantity(page, quantity);

    await expect(page).toHaveURL(`${baseUrl}/cart`);
    await expect(page.getByTestId("cart-heading")).toContainText(`Cart (${quantity})`);
    await expect(page.getByText("Quantity:")).toContainText(`Quantity: ${quantity}`);

    // Line-item total is unit price x quantity; cart total adds flat shipping.
    const lineTotal = (unitPrice * quantity).toFixed(2);
    const cartTotal = (unitPrice * quantity + shipping).toFixed(2);
    await expect(
        page.locator('.row').filter({ hasText: `Quantity: ${quantity}` }).locator('strong')
    ).toContainText(`$${lineTotal}`);
    await expect(page.locator('.cart-summary-total-row')).toContainText(`$${cartTotal}`);
    await expect(page.getByTestId("place-order-btn")).toContainText("Place Order");
});
